1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"strconv"
11		"unicode/utf8"
12	)
13	
14	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
15	// truncated JSON, trailing data after the object, an unknown version,
16	// missing, mistyped, unknown, or duplicated fields, a null where version,
17	// tip, height, hash, parent, or a transaction identifier is required,
18	// heights that do not ascend consecutively from 1, an empty or duplicated
19	// hash, a broken parent link, a version-2 timestamp that is missing or
20	// neither null nor a non-negative integer, a hash, parent, or transaction
21	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
22	// misordered Unicode surrogate escapes, or a tip that disagrees with the
23	// block list. A rejected restore never changes the index.
24	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
25	
26	const (
27		// snapshotVersion1 is the timestamp-less layout. It stays readable
28		// indefinitely; its blocks restore with missing timestamps.
29		snapshotVersion1 = 1
30		// snapshotVersion2 adds a required timestamp field to every block:
31		// either a non-negative Unix-seconds integer or null for missing time.
32		snapshotVersion2 = 2
33	)
34	
35	// snapshotDoc is the wire form of an exported main chain. Both layout
36	// versions share one shape: Version selects whether every block carries its
37	// Timestamp field.
38	type snapshotDoc struct {
39		Version int64           `json:"version"`
40		Tip     int64           `json:"tip"`
41		Blocks  []snapshotBlock `json:"blocks"`
42	}
43	
44	// snapshotBlock is the wire form of one block, shared by both versions.
45	// Height, hash, parent, and the transaction list follow the same rules in
46	// either layout. The timestamp is version 2 only and carried as a raw
47	// literal: nil is omitted altogether (version 1), "null" marks a missing
48	// time, and integer bytes render the Unix-seconds value (version 2). It
49	// stays the final field in every layout.
50	type snapshotBlock struct {
51		Height    int64           `json:"height"`
52		Hash      string          `json:"hash"`
53		Parent    string          `json:"parent"`
54		Txs       []string        `json:"txs"`
55		Timestamp json.RawMessage `json:"timestamp,omitempty"`
56	}
57	
58	// Export writes the current main chain to w as a JSON snapshot: a single
59	// object with version, tip, and the blocks ordered by ascending height, each
60	// carrying its transactions in order. The same main chain always produces
61	// the same bytes, regardless of the reorg, restore, or query history that
62	// led to it. Only blocks in effect at export time appear; nothing the index
63	// once held and later dropped is included.
64	//
65	// A chain whose blocks all lack timestamps keeps the original version-1
66	// layout, byte for byte. As soon as any block carries a timestamp the
67	// document is version 2 and every block includes a timestamp field: a
68	// non-negative integer or null for a missing timestamp.
69	//
70	// Export observes one complete chain state and never modifies the index.
71	// The chain is copied under the lock and serialized afterwards, so queries
72	// and appends proceed while the stream is still being written. A write
73	// failure is reported and leaves the index untouched.
74	func (index *Index) Export(w io.Writer) error {
75		doc := index.snapshotChain()
76		raw, err := json.Marshal(doc)
77		if err != nil {
78			panic(err) // snapshot docs only contain marshalable fields
79		}
80		n, err := w.Write(raw)
81		if err != nil {
82			return fmt.Errorf("indexroom: export snapshot: %w", err)
83		}
84		if n != len(raw) {
85			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
86		}
87		return nil
88	}
89	
90	// snapshotChain copies the current main chain into the export wire
91	// form: blocks by ascending height, each with its transactions copied in
92	// original order. This is the single place that turns stored blocks into the
93	// shared document fields, so both layout versions keep identical rules for
94	// height, hash, parent, and the transaction list; the only version-dependent
95	// field is the timestamp literal.
96	//
97	// The version is selected from the same chain copy. Any block carrying a
98	// timestamp — even a zero — makes the document version 2, after which every
99	// block gets a timestamp field, null where its time is missing; a chain
100	// whose blocks all lack times stays version 1 with no timestamp field.
101	func (index *Index) snapshotChain() snapshotDoc {
102		index.mu.Lock()
103		defer index.mu.Unlock()
104		version := int64(snapshotVersion1)
105		for height := int64(1); height <= index.Tip; height++ {
106			if index.Blocks[height].Time != nil {
107				version = snapshotVersion2
108				break
109			}
110		}
111		doc := snapshotDoc{
112			Version: version,
113			Tip:     index.Tip,
114			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
115		}
116		for height := int64(1); height <= index.Tip; height++ {
117			block := index.Blocks[height]
118			txs := make([]string, len(block.Txs))
119			copy(txs, block.Txs)
120			entry := snapshotBlock{
121				Height: block.Height,
122				Hash:   block.Hash,
123				Parent: block.Parent,
124				Txs:    txs,
125			}
126			if version == snapshotVersion2 {
127				entry.Timestamp = snapshotTimestampLiteral(block.Time)
128			}
129			doc.Blocks = append(doc.Blocks, entry)
130		}
131		return doc
132	}
133	
134	// snapshotMissingTimestamp is the raw JSON literal written for a block whose
135	// time is missing in a version-2 document.
136	var snapshotMissingTimestamp = json.RawMessage("null")
137	
138	// snapshotTimestampLiteral renders a stored block time as its version-2
139	// timestamp literal: null for a missing time, otherwise its non-negative
140	// Unix-seconds value as a bare integer. Stored times are guaranteed
141	// non-negative by Append, Reorg, and Restore validation.
142	func snapshotTimestampLiteral(time *int64) json.RawMessage {
143		if time == nil {
144			return snapshotMissingTimestamp
145		}
146		return json.RawMessage(strconv.AppendInt(nil, *time, 10))
147	}
148	
149	// restoreAppliedHookLocked is a test-only rendezvous invoked from Restore
150	// once the snapshot chain has fully replaced the old main chain, while
151	// index.mu is still held and before the call returns. It is nil in
152	// production; restore regression tests park a successful restore here with
153	// the new chain already in effect, so a QueryTimeStats issued at that
154	// instant is forced to wait and, once it runs, must observe the complete
155	// new chain.
156	var restoreAppliedHookLocked func(newTip int64)
157	
158	// Restore replaces the whole main chain with the snapshot read from r. The
159	// input must be exactly one snapshot object, optionally followed by
160	// whitespace; every block is validated — including heights ascending from 1,
161	// non-empty unique hashes, and parent linkage — before anything is applied.
162	// The first block's parent is exempt from linkage: it names the chain start
163	// and need not be indexed.
164	//
165	// The replacement takes effect as one complete operation: on success the
166	// index holds exactly the snapshot chain with no leftover heights or hashes,
167	// and on any failure — a read error or an invalid block discovered at the
168	// very end — the current chain and every previously issued cursor remain as
169	// they were. The stream is consumed and validated before the lock is taken,
170	// so the index stays queryable and appendable while the restore is reading.
171	//
172	// After a successful restore, cursors issued earlier by this same index keep
173	// working wherever the pinned range still matches and the tip still covers
174	// it; otherwise continuations fail with ErrQueryChanged as usual.
175	func (index *Index) Restore(r io.Reader) error {
176		tip, blocks, err := parseSnapshot(r)
177		if err != nil {
178			return err
179		}
180		stored := make(map[int64]Block, len(blocks))
181		byHash := make(map[string]int64, len(blocks))
182		for _, block := range blocks {
183			stored[block.Height] = block
184			byHash[block.Hash] = block.Height
185		}
186		index.mu.Lock()
187		index.Blocks = stored
188		index.ByHash = byHash
189		index.Tip = tip
190		if restoreAppliedHookLocked != nil {
191			restoreAppliedHookLocked(tip)
192		}
193		index.mu.Unlock()
194		return nil
195	}
196	
197	// parseSnapshot reads and fully validates one snapshot document. It returns
198	// the tip height and the validated blocks in ascending height order.
199	func parseSnapshot(r io.Reader) (int64, []Block, error) {
200		dec := json.NewDecoder(r)
201		tok, err := dec.Token()
202		if err != nil {
203			return 0, nil, classifySnapshotErr(err)
204		}
205		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
206			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
207		}
208	
209		// Top-level fields are captured raw so blocks can be parsed with the
210		// strict schema matching the declared version, whatever the field order,
211		// and so null can be told apart from a zero value.
212		var (
213			rawVersion, rawTip   json.RawMessage
214			rawBlocks            json.RawMessage
215			haveVersion, haveTip bool
216			haveBlocks           bool
217			seen                 = map[string]bool{}
218		)
219		for dec.More() {
220			key, err := snapshotKey(dec)
221			if err != nil {
222				return 0, nil, err
223			}
224			if seen[key] {
225				return 0, nil, invalidSnapshot("duplicate field %q", key)
226			}
227			seen[key] = true
228			switch key {
229			case "version":
230				if err := dec.Decode(&rawVersion); err != nil {
231					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
232				}
233				haveVersion = true
234			case "tip":
235				if err := dec.Decode(&rawTip); err != nil {
236					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
237				}
238				haveTip = true
239			case "blocks":
240				if err := dec.Decode(&rawBlocks); err != nil {
241					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
242				}
243				haveBlocks = true
244			default:
245				return 0, nil, invalidSnapshot("unknown field %q", key)
246			}
247		}
248		if _, err := dec.Token(); err != nil { // closing '}'
249			return 0, nil, classifySnapshotErr(err)
250		}
251		// Only whitespace may follow the snapshot object.
252		if _, err := dec.Token(); err != io.EOF {
253			if err == nil {
254				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
255			}
256			return 0, nil, classifySnapshotErr(err)
257		}
258	
259		if !haveVersion {
260			return 0, nil, invalidSnapshot("missing field %q", "version")
261		}
262		if !haveTip {
263			return 0, nil, invalidSnapshot("missing field %q", "tip")
264		}
265		if !haveBlocks {
266			return 0, nil, invalidSnapshot("missing field %q", "blocks")
267		}
268		version, err := snapshotInt64(rawVersion, "version")
269		if err != nil {
270			return 0, nil, err
271		}
272		tip, err := snapshotInt64(rawTip, "tip")
273		if err != nil {
274			return 0, nil, err
275		}
276		if version != snapshotVersion1 && version != snapshotVersion2 {
277			return 0, nil, invalidSnapshot("unsupported version %d", version)
278		}
279	
280		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
281		blocks, err := parseSnapshotBlocks(blockDec, version)
282		if err != nil {
283			return 0, nil, err
284		}
285		if _, err := blockDec.Token(); err != io.EOF {
286			if err == nil {
287				return 0, nil, invalidSnapshot("trailing data after the blocks array")
288			}
289			return 0, nil, classifySnapshotErr(err)
290		}
291	
292		lastHeight := int64(0)
293		if len(blocks) > 0 {
294			lastHeight = blocks[len(blocks)-1].Height
295		}
296		if tip != lastHeight {
297			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
298		}
299		return tip, blocks, nil
300	}
301	
302	// parseSnapshotBlocks reads the blocks array value, validating heights,
303	// hashes, parent links, and (for version 2) timestamps as it goes.
304	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
305		tok, err := dec.Token()
306		if err != nil {
307			return nil, classifySnapshotErr(err)
308		}
309		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
310			return nil, invalidSnapshot("field %q must be an array", "blocks")
311		}
312		blocks := []Block{}
313		seenHash := map[string]bool{}
314		for dec.More() {
315			var block Block
316			if version == snapshotVersion2 {
317				block, err = parseSnapshotBlockV2(dec)
318			} else {
319				block, err = parseSnapshotBlock(dec)
320			}
321			if err != nil {
322				return nil, err
323			}
324			want := int64(len(blocks) + 1)
325			if block.Height != want {
326				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
327			}
328			if block.Hash == "" {
329				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
330			}
331			if seenHash[block.Hash] {
332				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
333			}
334			seenHash[block.Hash] = true
335			// The first block's parent names the chain start and is exempt from
336			// linkage; every later block must point at its predecessor.
337			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
338				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
339			}
340			blocks = append(blocks, block)
341		}
342		if _, err := dec.Token(); err != nil { // closing ']'
343			return nil, classifySnapshotErr(err)
344		}
345		return blocks, nil
346	}
347	
348	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
349	// fields height, hash, parent, and txs.
350	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
351		var block Block
352		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
353		if err != nil {
354			return block, err
355		}
356		return finishSnapshotBlock(fields)
357	}
358	
359	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
360	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
361	// null or a non-negative integer; the block returns a nil time for null.
362	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
363		var block Block
364		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
365		if err != nil {
366			return block, err
367		}
368		if _, ok := fields["timestamp"]; !ok {
369			return block, invalidSnapshot("block is missing field %q", "timestamp")
370		}
371		block, err = finishSnapshotBlock(fields)
372		if err != nil {
373			return block, err
374		}
375		t, err := parseSnapshotTimestamp(fields["timestamp"])
376		if err != nil {
377			return Block{}, err
378		}
379		block.Time = t
380		return block, nil
381	}
382	
383	// readSnapshotBlockObject reads one block object and captures each known
384	// field's raw value. Fields are decoded only after the whole object is read,
385	// so a null can be rejected per field and a txs element error can name the
386	// block's height whatever order the fields arrive in.
387	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
388		tok, err := dec.Token()
389		if err != nil {
390			return nil, classifySnapshotErr(err)
391		}
392		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
393			return nil, invalidSnapshot("block must be a JSON object")
394		}
395		fields := map[string]json.RawMessage{}
396		for dec.More() {
397			key, err := snapshotKey(dec)
398			if err != nil {
399				return nil, err
400			}
401			if _, dup := fields[key]; dup {
402				return nil, invalidSnapshot("duplicate block field %q", key)
403			}
404			if !slices.Contains(known, key) {
405				return nil, invalidSnapshot("unknown block field %q", key)
406			}
407			var raw json.RawMessage
408			if err := dec.Decode(&raw); err != nil {
409				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
410			}
411			fields[key] = raw
412		}
413		if _, err := dec.Token(); err != nil { // closing '}'
414			return nil, classifySnapshotErr(err)
415		}
416		return fields, nil
417	}
418	
419	// finishSnapshotBlock decodes the shared block fields from their raw values,
420	// requiring height, hash, parent, and txs and rejecting null for each.
421	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
422		var block Block
423		for _, field := range []string{"height", "hash", "parent", "txs"} {
424			if _, ok := fields[field]; !ok {
425				return block, invalidSnapshot("block is missing field %q", field)
426			}
427		}
428		var err error
429		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
430			return block, err
431		}
432		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
433			return block, err
434		}
435		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
436			return block, err
437		}
438		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
439		if err != nil {
440			return block, err
441		}
442		block.Txs = txs
443		return block, nil
444	}
445	
446	// snapshotInt64 decodes one required integer field, rejecting null rather
447	// than letting it pass as zero.
448	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
449		if isSnapshotNull(raw) {
450			return 0, invalidSnapshot("field %q must not be null", field)
451		}
452		var v int64
453		if err := json.Unmarshal(raw, &v); err != nil {
454			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
455		}
456		return v, nil
457	}
458	
459	// snapshotString decodes one required string field, rejecting null rather
460	// than letting it pass as the empty string. The raw literal is also checked
461	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
462	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
463	// height identifies the block the field belongs to in the error.
464	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
465		if isSnapshotNull(raw) {
466			return "", invalidSnapshot("field %q must not be null", field)
467		}
468		var s string
469		if err := json.Unmarshal(raw, &s); err != nil {
470			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
471		}
472		if !validSnapshotString(raw) {
473			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
474		}
475		return s, nil
476	}
477	
478	// isSnapshotNull reports whether a raw field value is the JSON null literal.
479	func isSnapshotNull(raw json.RawMessage) bool {
480		return string(raw) == "null"
481	}
482	
483	// validSnapshotString reports whether raw is a JSON string literal whose
484	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
485	// misordered surrogates. The JSON decoder accepts both defects silently,
486	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
487	// the raw bytes are checked here before the decoded value is trusted. A
488	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
489	// UTF-8 and passes.
490	func validSnapshotString(raw json.RawMessage) bool {
491		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
492			return false
493		}
494		body := raw[1 : len(raw)-1]
495		for i := 0; i < len(body); {
496			b := body[i]
497			switch {
498			case b == '\\':
499				if i+1 >= len(body) {
500					return false
501				}
502				if body[i+1] != 'u' {
503					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
504					continue
505				}
506				code, ok := snapshotHex4(body, i+2)
507				if !ok {
508					return false
509				}
510				i += 6
511				switch {
512				case code >= 0xD800 && code <= 0xDBFF:
513					// A high surrogate is only valid as the first half of a
514					// pair; the low half must follow immediately as an escape.
515					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
516						return false
517					}
518					low, ok := snapshotHex4(body, i+2)
519					if !ok || low < 0xDC00 || low > 0xDFFF {
520						return false
521					}
522					i += 6
523				case code >= 0xDC00 && code <= 0xDFFF:
524					return false // a low surrogate cannot appear on its own
525				}
526			case b < utf8.RuneSelf:
527				i++
528			default:
529				// DecodeRune returns RuneError with size 1 for invalid
530				// encoding; a genuine U+FFFD decodes with size 3.
531				r, size := utf8.DecodeRune(body[i:])
532				if r == utf8.RuneError && size <= 1 {
533					return false
534				}
535				i += size
536			}
537		}
538		return true
539	}
540	
541	// snapshotHex4 reads four hexadecimal digits starting at b[i].
542	func snapshotHex4(b []byte, i int) (rune, bool) {
543		if i+4 > len(b) {
544			return 0, false
545		}
546		var v rune
547		for _, c := range b[i : i+4] {
548			var d byte
549			switch {
550			case '0' <= c && c <= '9':
551				d = c - '0'
552			case 'a' <= c && c <= 'f':
553				d = c - 'a' + 10
554			case 'A' <= c && c <= 'F':
555				d = c - 'A' + 10
556			default:
557				return 0, false
558			}
559			v = v*16 + rune(d)
560		}
561		return v, true
562	}
563	
564	// parseSnapshotTimestamp reads one timestamp value: null for a missing
565	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
566	// distinct from null.
567	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
568		var t *int64
569		if err := json.Unmarshal(raw, &t); err != nil {
570			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
571		}
572		if t != nil && *t < 0 {
573			return nil, invalidSnapshot("timestamp must not be negative")
574		}
575		return t, nil
576	}
577	
578	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
579	// identifiers exactly as written. A null element is rejected, naming the
580	// block's height and the element's zero-based position, and so is an
581	// element whose raw string carries invalid UTF-8 bytes or unpaired or
582	// misordered surrogate escapes.
583	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
584		tok, err := dec.Token()
585		if err != nil {
586			return nil, classifySnapshotErr(err)
587		}
588		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
589			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
590		}
591		txs := []string{}
592		for dec.More() {
593			var raw json.RawMessage
594			if err := dec.Decode(&raw); err != nil {
595				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
596			}
597			if isSnapshotNull(raw) {
598				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
599			}
600			var tx string
601			if err := json.Unmarshal(raw, &tx); err != nil {
602				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
603			}
604			if !validSnapshotString(raw) {
605				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
606			}
607			txs = append(txs, tx)
608		}
609		if _, err := dec.Token(); err != nil { // closing ']'
610			return nil, classifySnapshotErr(err)
611		}
612		return txs, nil
613	}
614	
615	// snapshotKey reads the next object key.
616	func snapshotKey(dec *json.Decoder) (string, error) {
617		tok, err := dec.Token()
618		if err != nil {
619			return "", classifySnapshotErr(err)
620		}
621		key, ok := tok.(string)
622		if !ok {
623			return "", invalidSnapshot("object key must be a string")
624		}
625		return key, nil
626	}
627	
628	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
629	func invalidSnapshot(format string, args ...any) error {
630		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
631	}
632	
633	// classifySnapshotErr maps decoder failures onto the snapshot error model:
634	// malformed JSON, wrong value types, and truncation are snapshot errors,
635	// while anything else is an underlying read failure reported as-is.
636	func classifySnapshotErr(err error) error {
637		var syntaxErr *json.SyntaxError
638		var typeErr *json.UnmarshalTypeError
639		switch {
640		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
641			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
642		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
643			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
644		default:
645			return fmt.Errorf("indexroom: read snapshot: %w", err)
646		}
647	}
648

