217	// gatedReader delivers the first prefix bytes of data, then parks until
218	// release is closed, then delivers the rest. It lets a test hold Restore
219	// mid-parse — after whole blocks have already been consumed but before the
220	// replacement is applied — without any sleeps or scheduling luck.
221	type gatedReader struct {
222		data    []byte
223		prefix  int
224		off     int
225		entered chan struct{}
226		release chan struct{}
227		once    sync.Once
228	}
