441	// Deterministic rendezvous for the QueryTxs/Reorg overlap tests. A parked
442	// first page holds the lock with its tip already pinned; a parked
443	// continuation holds it after every pinned-range check has passed; a parked
444	// reorg has the new branch fully applied but has not returned.
445	type queryReorgHooks struct {
446		firstParked  chan struct{}
447		releaseFirst chan struct{}
448		contParked   chan struct{}
449		releaseCont  chan struct{}
450		reorgParked  chan struct{}
451		releaseReorg chan struct{}
452	
453		allowedReorgTips map[int64]bool
454		firstOnce        sync.Once
455		contOnce         sync.Once
456		reorgOnce        sync.Once
457	}
458	
459	func installQueryReorgHooks(t *testing.T, parkFirst, parkCont bool, reorgTips ...int64) *queryReorgHooks {
460		t.Helper()
461		h := &queryReorgHooks{
462			reorgParked:  make(chan struct{}),
463			releaseReorg: make(chan struct{}),
464		}
465		if parkFirst {
466			h.firstParked = make(chan struct{})
467			h.releaseFirst = make(chan struct{})
468		}
469		if parkCont {
470			h.contParked = make(chan struct{})
471			h.releaseCont = make(chan struct{})
472		}
473		if len(reorgTips) > 0 {
474			h.allowedReorgTips = map[int64]bool{}
475			for _, tip := range reorgTips {
476				h.allowedReorgTips[tip] = true
477			}
478		}
479		queryTxsHookLocked = func(from, to int64, continuation bool) {
480			switch {
481			case continuation && h.contParked != nil:
482				h.contOnce.Do(func() { close(h.contParked) })
483				<-h.releaseCont
484			case !continuation && h.firstParked != nil:
485				h.firstOnce.Do(func() { close(h.firstParked) })
486				<-h.releaseFirst
487			}
488		}
489		reorgAppliedHookLocked = func(newTip int64) {
490			if h.allowedReorgTips != nil && !h.allowedReorgTips[newTip] {
491				t.Errorf("reorg hook saw newTip=%d, want one of %v", newTip, h.allowedReorgTips)
492			}
493			h.reorgOnce.Do(func() { close(h.reorgParked) })
494			<-h.releaseReorg
495		}
496		t.Cleanup(func() {
497			queryTxsHookLocked = nil
498			reorgAppliedHookLocked = nil
499		})
500		return h
501	}
