503	// decodePayload exposes the signed cursor contents within the package so a
504	// test can prove which branch a cursor pins (upper height, offset, range
505	// fingerprint) without using it.
506	func decodePayload(t *testing.T, index *Index, cursor string) cursorPayload {
507		t.Helper()
508		payload, err := index.decodeCursor(cursor)
509		if err != nil {
510			t.Fatalf("cursor not decodable on its own index: %v", err)
511		}
512		return payload
513	}
